questionvariables.text:
/* Curated angle pairs [ang1, ang2] for sin(ang1) + cos(ang2).
   Every pair uses two different angles, and the two values are like terms, so the answer is
   always one of 1, -1, sqrt(2), -sqrt(2), sqrt(3), -sqrt(3): never 0 and never a mixed surd. */
pairs : [[-30,-120],[-30,-240],[-45,-135],[-45,-225],[-60,-150],[-60,-210],[-120,-150],[-120,-210],[-135,-225],[-150,-120],[-150,-240],[-210,-60],[-210,-300],[-225,-45],[-225,-315],[-240,-30],[-240,-330],[-300,-30],[-300,-330],[-315,-45],[-330,-60],[-330,-300]];
pr : rand(pairs);
ang1 : pr[1];
ang2 : pr[2];

/* Positive angles after using sin(-t) = -sin(t) and cos(-t) = cos(t) */
t1 : -ang1;
t2 : -ang2;

/* Quadrant and reference angle of each positive angle */
q1 : if t1 < 90 then 1 else if t1 < 180 then 2 else if t1 < 270 then 3 else 4;
q2 : if t2 < 90 then 1 else if t2 < 180 then 2 else if t2 < 270 then 3 else 4;
ref1 : if q1 = 1 then t1 else if q1 = 2 then 180 - t1 else if q1 = 3 then t1 - 180 else 360 - t1;
ref2 : if q2 = 1 then t2 else if q2 = 2 then 180 - t2 else if q2 = 3 then t2 - 180 else 360 - t2;
quadnames : ["I", "II", "III", "IV"];
qn1 : quadnames[q1];
qn2 : quadnames[q2];

/* Exact values */
sref1 : sin(ref1*%pi/180);        /* sin of the reference angle (no sign) */
cref2 : cos(ref2*%pi/180);        /* cos of the reference angle (no sign) */
s1 : sin(t1*%pi/180);             /* sin of the positive angle */
c2 : cos(t2*%pi/180);             /* cos of the positive angle */
sin_ans : -s1;                    /* sin(ang1) = -sin(t1) */
cos_ans : c2;                     /* cos(ang2) = cos(t2) */
ta : sin_ans + cos_ans;

/* Possible student mistakes */
sin_neg : -sin_ans;               /* forgot sin(-t) = -sin(t), or wrong quadrant sign */
cos_neg : -cos_ans;               /* wrong sign for cos */
sin_mag_swap : cos(ref1*%pi/180); /* used the cos of the reference angle (either sign) */
cos_mag_swap : sin(ref2*%pi/180); /* used the sin of the reference angle (either sign) */
